using System;using SarmatVisionHold.KestrelClient.Models;
namespace SarmatVisionHold.KestrelClient.Processing {
 /// <summary>Axes: body +X right, +Y up, +Z aft (Kestrel); image +X right/+Y down. Camera mount uses intrinsic roll/pitch/yaw. Texture motion is opposite projected camera translation. Positive image rotation is CCW.</summary>
 public sealed class GroundTruthMotionEstimator { readonly double translationEpsilon,yawEpsilon;public GroundTruthMotionEstimator(double translationEpsilon=.05,double yawEpsilon=.02){this.translationEpsilon=translationEpsilon;this.yawEpsilon=yawEpsilon;}
  public GroundTruthMotion Estimate(KestrelTelemetry t){if(t?.VelocityBody==null||t.Camera==null||t.AngularRateBody==null)return new GroundTruthMotion();var v=Rotate(t.VelocityBody,t.Camera.MountRollRad,t.Camera.MountPitchRad,t.Camera.MountYawRad);var tx=-v.X;var ty=v.Y;var moving=Math.Sqrt(tx*tx+ty*ty)>=translationEpsilon;var rotating=Math.Abs(t.AngularRateBody.Z)>=yawEpsilon;return new GroundTruthMotion{CameraX=v.X,CameraY=v.Y,YawRate=t.AngularRateBody.Z,TextureDirection=moving?Direction(tx,ty):"STILL",RotationDirection=rotating?(t.AngularRateBody.Z>0?"CW":"CCW"):"STILL",Classification=moving&&rotating?ExpectedMotion.Mixed:moving?ExpectedMotion.Translating:rotating?ExpectedMotion.Rotating:ExpectedMotion.Still};}
  static Vector3Data Rotate(Vector3Data v,double roll,double pitch,double yaw){var cr=Math.Cos(roll);var sr=Math.Sin(roll);var cp=Math.Cos(pitch);var sp=Math.Sin(pitch);var cy=Math.Cos(yaw);var sy=Math.Sin(yaw);return new Vector3Data{X=(cy*cp)*v.X+(cy*sp*sr-sy*cr)*v.Y+(cy*sp*cr+sy*sr)*v.Z,Y=(sy*cp)*v.X+(sy*sp*sr+cy*cr)*v.Y+(sy*sp*cr-cy*sr)*v.Z,Z=(-sp)*v.X+(cp*sr)*v.Y+(cp*cr)*v.Z};}static string Direction(double x,double y){var h=x>=0?"RIGHT":"LEFT";var v=y>=0?"DOWN":"UP";var ax=Math.Abs(x);var ay=Math.Abs(y);return ax>ay*1.8?h:ay>ax*1.8?v:h+"+"+v;}
 }
}
